#!/bin/bash
# Installs Sketch into Claude Code by generating agents and skills under ~/.claude, and by
# copying the deterministic tools (tools/) with a launcher per tool.
#
#   install.sh             install or update
#   install.sh uninstall   remove only what this script generated
#
# The generated files carry a marker line. The script refuses to overwrite a file
# without that marker, so it never touches anything you wrote yourself.
# It does not edit your settings.json. See settings.snippet.json and README.md.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
CORE="$ROOT/core"
LIST="$ROOT/adapters/claude-code/agents.list"
DEST="${CLAUDE_HOME:-$HOME/.claude}"
# a filled-in copy of all of core/, so every {{CORE}}/... reference opens a file
# whose own references are already resolved
CORE_OUT="$DEST/sketch/core"
# the tools: a copy of tools/sketch_tools, one launcher per tool, and the entry script they share
TOOLS_SRC="$ROOT/tools/sketch_tools"
TOOLS_OUT="$DEST/sketch/tools"
TOOLS_BIN="$TOOLS_OUT/bin"
[ -f "$ROOT/VERSION" ] || { echo "STOPPED: $ROOT/VERSION is missing" >&2; exit 1; }
VERSION="$(tr -d '[:space:]' < "$ROOT/VERSION")"
MARK="<!-- generated by sketch adapters/claude-code/install.sh (sketch $VERSION). Edit core/ in the Sketch repo and rerun the script. -->"
MARK_KEY='generated by sketch adapters/claude-code/install.sh'

fail() { echo "STOPPED: $*" >&2; exit 1; }

# true when the file does not exist yet, or was generated by this script
may_write() { [ ! -e "$1" ] || grep -qF -- "$MARK_KEY" "$1"; }
# true only when the file exists and was generated by this script
is_ours() { [ -f "$1" ] && grep -qF -- "$MARK_KEY" "$1"; }

# expand SRC DST [TOOLS MODEL]: fill {{CORE}}, {{CORE_SOURCE}}, {{TOOLS}} and {{VERSION}}, add the marker
# (after the frontmatter if there is one, else on top), and tools/model when given
expand() {
  awk -v mark="$MARK" -v core="$CORE_OUT" -v src_core="$CORE" -v version="$VERSION" -v tools_bin="$TOOLS_BIN" -v tools="${3:-}" -v model="${4:-}" '
    NR == 1 && $0 != "---" { print mark; fm = -1 }
    NR == 1 && $0 == "---" { fm = 1; print; next }
    fm == 1 && $0 == "---" {
      if (tools != "") print "tools: " tools
      if (model != "") print "model: " model
      print; print mark; fm = -1; next
    }
    { gsub(/\{\{CORE\}\}/, core); gsub(/\{\{CORE_SOURCE\}\}/, src_core); gsub(/\{\{TOOLS\}\}/, tools_bin); gsub(/\{\{VERSION\}\}/, version); print }
  ' "$1" > "$2"
}

# the names of the tools: every package under tools/sketch_tools with a __main__.py, except core
tool_modules() {
  for d in "$TOOLS_SRC"/*/; do
    [ -f "${d}__main__.py" ] && basename "$d"
  done
}
launcher_name() { echo "sketch-$(echo "$1" | tr '_' '-')"; }

need_python() {
  python3 -c 'import sys; raise SystemExit(0 if sys.version_info >= (3, 9) else 1)' 2>/dev/null \
    || fail "Python 3.9 or newer is required for the tools (python3 was not found or is too old)."
}

[ -d "$CORE/agents" ] && [ -d "$CORE/skills" ] || fail "core/agents or core/skills is missing under $ROOT"
[ -f "$LIST" ] || fail "$LIST is missing"

if [ "${1:-}" = "uninstall" ]; then
  for f in "$DEST"/agents/*.md; do
    if is_ours "$f"; then rm "$f"; echo "removed agent $(basename "$f" .md)"; fi
  done
  for f in "$DEST"/skills/*/SKILL.md; do
    if is_ours "$f"; then
      rm "$f"
      rmdir "$(dirname "$f")" 2>/dev/null || true
      echo "removed skill $(basename "$(dirname "$f")")"
    fi
  done
  if [ -d "$CORE_OUT" ]; then
    find "$CORE_OUT" -type f -name '*.md' | while read -r f; do
      if is_ours "$f"; then rm "$f"; fi
    done
    echo "removed $CORE_OUT"
  fi
  if [ -d "$TOOLS_OUT" ]; then
    for f in "$TOOLS_BIN"/* "$TOOLS_OUT/run.py"; do
      if is_ours "$f"; then rm "$f"; fi
    done
    if [ -f "$TOOLS_OUT/.sketch-generated" ]; then
      rm -rf "$TOOLS_OUT/sketch_tools"
      rm "$TOOLS_OUT/.sketch-generated"
    fi
    echo "removed $TOOLS_OUT"
  fi
  [ -d "$DEST/sketch" ] && find "$DEST/sketch" -depth -type d -empty -delete 2>/dev/null || true
  exit 0
fi

# every agent file must be listed, so nothing is silently left out
for f in "$CORE"/agents/*.md; do
  n="$(basename "$f" .md)"
  grep -q "^${n}|" "$LIST" || fail "core/agents/$n.md is not listed in agents.list"
done

# the tools: check everything before writing anything
[ -d "$TOOLS_SRC/core" ] || fail "tools/sketch_tools is missing under $ROOT"
need_python
may_write "$TOOLS_OUT/run.py" || fail "$TOOLS_OUT/run.py exists and was not generated by this script. Move it away."
if [ -e "$TOOLS_OUT/sketch_tools" ] && [ ! -f "$TOOLS_OUT/.sketch-generated" ]; then
  fail "$TOOLS_OUT/sketch_tools exists and was not generated by this script. Move it away."
fi
for module in $(tool_modules); do
  may_write "$TOOLS_BIN/$(launcher_name "$module")" \
    || fail "$TOOLS_BIN/$(launcher_name "$module") exists and was not generated by this script. Move it away."
done

mkdir -p "$DEST/agents" "$DEST/skills" "$CORE_OUT"

# remove generated files that no longer have a source (an agent or skill that was deleted)
for f in "$DEST"/agents/*.md; do
  n="$(basename "$f" .md)"
  if is_ours "$f" && ! grep -q "^${n}|" "$LIST"; then rm "$f"; echo "removed stale agent $n"; fi
done
for f in "$DEST"/skills/*/SKILL.md; do
  n="$(basename "$(dirname "$f")")"
  if is_ours "$f" && [ ! -f "$CORE/skills/$n/SKILL.md" ]; then
    rm "$f"; rmdir "$(dirname "$f")" 2>/dev/null || true; echo "removed stale skill $n"
  fi
done
if [ -d "$CORE_OUT" ]; then
  find "$CORE_OUT" -type f -name '*.md' | while read -r f; do
    rel="${f#"$CORE_OUT"/}"
    if is_ours "$f" && [ ! -f "$CORE/$rel" ]; then rm "$f"; echo "removed stale core/$rel"; fi
  done
fi

# the filled-in copy of core/ that {{CORE}} points to
(cd "$CORE" && find . -type f -name '*.md') | while read -r rel; do
  dst="$CORE_OUT/${rel#./}"
  mkdir -p "$(dirname "$dst")"
  may_write "$dst" || fail "$dst exists and was not generated by this script. Move it away."
  expand "$CORE/${rel#./}" "$dst"
done
echo "core   $CORE_OUT"

# agents: add tools and model to the frontmatter, add the marker, fill the placeholders
while IFS='|' read -r name tools model; do
  case "$name" in ''|\#*) continue ;; esac
  src="$CORE/agents/$name.md"
  dst="$DEST/agents/$name.md"
  [ -f "$src" ] || fail "agents.list names '$name' but $src does not exist"
  may_write "$dst" || fail "$dst exists and was not generated by this script. Move it away or rename the agent."
  expand "$src" "$dst" "$tools" "$model"
  echo "agent  $name"
done < "$LIST"

# skills: add the marker, fill the placeholders
for d in "$CORE"/skills/*/; do
  name="$(basename "$d")"
  src="$d/SKILL.md"
  dst="$DEST/skills/$name/SKILL.md"
  [ -f "$src" ] || fail "$src does not exist"
  mkdir -p "$DEST/skills/$name"
  may_write "$dst" || fail "$dst exists and was not generated by this script. Move it away or rename the skill in core/skills."
  expand "$src" "$dst"
  echo "skill  $name"
done

# tools: a copy of the package, the shared entry script, and one launcher per tool
mkdir -p "$TOOLS_BIN"
rm -rf "$TOOLS_OUT/sketch_tools"
cp -R "$TOOLS_SRC" "$TOOLS_OUT/sketch_tools"
find "$TOOLS_OUT/sketch_tools" -name __pycache__ -type d -prune -exec rm -rf {} +
echo "$MARK" > "$TOOLS_OUT/.sketch-generated"
# python3 -I keeps the current folder and the user's environment out of the import path, so a
# project that contains its own argparse.py or sketch_tools/ cannot hijack a tool
cat > "$TOOLS_OUT/run.py" <<EOF
# $MARK_KEY (sketch $VERSION). Edit tools/ in the Sketch repo and rerun the script.
import importlib
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
module = sys.argv.pop(1)
sys.argv[0] = "sketch-" + module.replace("_", "-")
sys.exit(importlib.import_module("sketch_tools." + module).main())
EOF
for module in $(tool_modules); do
  launcher="$TOOLS_BIN/$(launcher_name "$module")"
  cat > "$launcher" <<EOF
#!/bin/sh
# $MARK_KEY (sketch $VERSION). Edit tools/ in the Sketch repo and rerun the script.
exec python3 -I "$TOOLS_OUT/run.py" $module "\$@"
EOF
  chmod +x "$launcher"
  echo "tool   $(launcher_name "$module")"
done

echo "Installed sketch $VERSION into $DEST. Restart Claude Code (or start a new session) to pick them up."
echo "Permissions are not changed. See adapters/claude-code/settings.snippet.json."
